-- SqlCodegenSpec.hs — hspec tests for the Haskell bytecode code generator.
--
-- Covers:
--   • compileExpr  — all expression forms (literals, columns, binary/unary ops,
--                    IsNull, IsNotNull, Between, Like, InList)
--   • compile      — all plan node types (Scan, Filter, Project, Aggregate,
--                    Sort, Limit, Distinct, Insert, Update, Delete,
--                    CreateTable, DropTable, EmptyResult)
--
-- Tests check the exact instruction sequences produced, validating both the
-- structure of the generated bytecode and the labelling scheme.
--
-- IMPORTANT: SqlPlanner is imported qualified as `P` to avoid name collision
-- with Instruction constructors. SqlExpr constructors are written as
-- P.Literal, P.Column, P.IsNull, P.BinaryOp, etc.

module SqlCodegenSpec (spec) where

import Test.Hspec

import SqlCodegen
import qualified SqlPlanner as P
import SqlPlanner
    ( LiteralVal(..)
    , BinaryOperator(..)
    , UnaryOperator(..)
    , AggFunction(..)
    , AggArg(..)
    , SortKey(..)
    , AggregateItem(..)
    , OutputColumn(..)
    , ColumnDef(..)
    )
import SqlOptimizer
    ( OptimizedPlan(..)
    )

-- ── Helpers ───────────────────────────────────────────────────────────────

-- | Shorthand: compile a plan and extract the instruction list.
instrs :: OptimizedPlan -> [Instruction]
instrs = instructions . compile

-- | Build a minimal OptScan with no required-column hints.
mkScan :: String -> Maybe String -> OptimizedPlan
mkScan t a = OptScan t a Nothing Nothing

-- | A minimal ColumnDef for DDL tests.
colDef :: String -> ColumnDef
colDef name = ColumnDef name "INTEGER" False False False Nothing

-- ── Spec ──────────────────────────────────────────────────────────────────

spec :: Spec
spec = do

    -- ────────────────────────────────────────────────────────────────────
    -- 1. Expression compiler
    -- ────────────────────────────────────────────────────────────────────

    describe "compileExpr" $ do

        describe "literals" $ do

            it "compiles integer literal" $
                compileExpr (P.Literal (Just (LitInt 42)))
                    `shouldBe` [LoadConst (LitInt 42)]

            it "compiles real literal" $
                compileExpr (P.Literal (Just (LitReal 3.14)))
                    `shouldBe` [LoadConst (LitReal 3.14)]

            it "compiles text literal" $
                compileExpr (P.Literal (Just (LitText "hello")))
                    `shouldBe` [LoadConst (LitText "hello")]

            it "compiles boolean literal True" $
                compileExpr (P.Literal (Just (LitBool True)))
                    `shouldBe` [LoadConst (LitBool True)]

            it "compiles NULL literal" $
                compileExpr (P.Literal Nothing)
                    `shouldBe` [LoadNull]

        describe "column references" $ do

            it "compiles qualified column reference" $
                compileExpr (P.Column (Just "u") "name")
                    `shouldBe` [LoadColumn (Just "u") "name"]

            it "compiles unqualified column reference" $
                compileExpr (P.Column Nothing "age")
                    `shouldBe` [LoadColumn Nothing "age"]

        describe "binary operators" $ do

            it "compiles Add" $
                compileExpr (P.BinaryOp BinAdd (P.Literal (Just (LitInt 1))) (P.Literal (Just (LitInt 2))))
                    `shouldBe` [ LoadConst (LitInt 1)
                               , LoadConst (LitInt 2)
                               , BinaryOpInstr Add ]

            it "compiles Sub" $
                compileExpr (P.BinaryOp BinSub (P.Column Nothing "x") (P.Literal (Just (LitInt 1))))
                    `shouldBe` [ LoadColumn Nothing "x"
                               , LoadConst (LitInt 1)
                               , BinaryOpInstr Sub ]

            it "compiles Mul" $
                compileExpr (P.BinaryOp BinMul (P.Column Nothing "a") (P.Column Nothing "b"))
                    `shouldBe` [ LoadColumn Nothing "a"
                               , LoadColumn Nothing "b"
                               , BinaryOpInstr Mul ]

            it "compiles Div" $
                compileExpr (P.BinaryOp BinDiv (P.Column Nothing "total") (P.Literal (Just (LitInt 10))))
                    `shouldBe` [ LoadColumn Nothing "total"
                               , LoadConst (LitInt 10)
                               , BinaryOpInstr Div ]

            it "compiles Mod" $
                compileExpr (P.BinaryOp BinMod (P.Column Nothing "n") (P.Literal (Just (LitInt 2))))
                    `shouldBe` [ LoadColumn Nothing "n"
                               , LoadConst (LitInt 2)
                               , BinaryOpInstr Mod ]

            it "compiles Eq" $
                compileExpr (P.BinaryOp BinEq (P.Column Nothing "id") (P.Literal (Just (LitInt 5))))
                    `shouldBe` [ LoadColumn Nothing "id"
                               , LoadConst (LitInt 5)
                               , BinaryOpInstr Eq ]

            it "compiles Neq" $
                compileExpr (P.BinaryOp BinNotEq (P.Column Nothing "status") (P.Literal (Just (LitText "inactive"))))
                    `shouldBe` [ LoadColumn Nothing "status"
                               , LoadConst (LitText "inactive")
                               , BinaryOpInstr Neq ]

            it "compiles Lt" $
                compileExpr (P.BinaryOp BinLt (P.Column Nothing "age") (P.Literal (Just (LitInt 18))))
                    `shouldBe` [ LoadColumn Nothing "age"
                               , LoadConst (LitInt 18)
                               , BinaryOpInstr Lt ]

            it "compiles Lte" $
                compileExpr (P.BinaryOp BinLte (P.Column Nothing "score") (P.Literal (Just (LitInt 100))))
                    `shouldBe` [ LoadColumn Nothing "score"
                               , LoadConst (LitInt 100)
                               , BinaryOpInstr Lte ]

            it "compiles Gt" $
                compileExpr (P.BinaryOp BinGt (P.Column Nothing "price") (P.Literal (Just (LitReal 0.0))))
                    `shouldBe` [ LoadColumn Nothing "price"
                               , LoadConst (LitReal 0.0)
                               , BinaryOpInstr Gt ]

            it "compiles Gte" $
                compileExpr (P.BinaryOp BinGte (P.Column Nothing "qty") (P.Literal (Just (LitInt 1))))
                    `shouldBe` [ LoadColumn Nothing "qty"
                               , LoadConst (LitInt 1)
                               , BinaryOpInstr Gte ]

            it "compiles And" $
                compileExpr (P.BinaryOp BinAnd
                    (P.BinaryOp BinGt (P.Column Nothing "age") (P.Literal (Just (LitInt 18))))
                    (P.BinaryOp BinLt (P.Column Nothing "age") (P.Literal (Just (LitInt 65)))))
                `shouldBe`
                    [ LoadColumn Nothing "age", LoadConst (LitInt 18), BinaryOpInstr Gt
                    , LoadColumn Nothing "age", LoadConst (LitInt 65), BinaryOpInstr Lt
                    , BinaryOpInstr And ]

            it "compiles Or" $
                compileExpr (P.BinaryOp BinOr
                    (P.BinaryOp BinEq (P.Column Nothing "role") (P.Literal (Just (LitText "admin"))))
                    (P.BinaryOp BinEq (P.Column Nothing "role") (P.Literal (Just (LitText "owner")))))
                `shouldBe`
                    [ LoadColumn Nothing "role", LoadConst (LitText "admin"), BinaryOpInstr Eq
                    , LoadColumn Nothing "role", LoadConst (LitText "owner"), BinaryOpInstr Eq
                    , BinaryOpInstr Or ]

        describe "unary operators" $ do

            it "compiles Neg" $
                compileExpr (P.UnaryOp UnaryNeg (P.Column Nothing "balance"))
                    `shouldBe` [ LoadColumn Nothing "balance"
                               , UnaryOpInstr Neg ]

            it "compiles Not" $
                compileExpr (P.UnaryOp UnaryNot
                    (P.BinaryOp BinEq (P.Column Nothing "active") (P.Literal (Just (LitBool True)))))
                    `shouldBe` [ LoadColumn Nothing "active"
                               , LoadConst (LitBool True)
                               , BinaryOpInstr Eq
                               , UnaryOpInstr Not ]

        describe "null tests" $ do

            it "compiles IsNull" $
                compileExpr (P.IsNull (P.Column Nothing "email"))
                    `shouldBe` [ LoadColumn Nothing "email"
                               , IsNullInstr ]

            it "compiles IsNotNull" $
                compileExpr (P.IsNotNull (P.Column Nothing "phone"))
                    `shouldBe` [ LoadColumn Nothing "phone"
                               , IsNotNullInstr ]

        describe "Between" $
            it "compiles Between to three pushes + BetweenInstr True" $
                compileExpr (P.Between
                    (P.Column Nothing "age")
                    (P.Literal (Just (LitInt 18)))
                    (P.Literal (Just (LitInt 65))))
                `shouldBe`
                    [ LoadColumn Nothing "age"
                    , LoadConst (LitInt 18)
                    , LoadConst (LitInt 65)
                    , BetweenInstr True ]

        describe "Like / NotLike" $ do

            it "compiles Like with pattern as const" $
                compileExpr (P.Like (P.Column Nothing "name") "Alice%")
                    `shouldBe` [ LoadColumn Nothing "name"
                               , LoadConst (LitText "Alice%")
                               , LikeInstr ]

            it "compiles NotLike as Like + Not" $
                compileExpr (P.NotLike (P.Column Nothing "email") "%@spam.com")
                    `shouldBe` [ LoadColumn Nothing "email"
                               , LoadConst (LitText "%@spam.com")
                               , LikeInstr
                               , UnaryOpInstr Not ]

        describe "InExpr / NotInExpr" $ do

            it "compiles InList with correct count" $
                compileExpr (P.InExpr (P.Column Nothing "id")
                    [ P.Literal (Just (LitInt 1))
                    , P.Literal (Just (LitInt 2))
                    , P.Literal (Just (LitInt 3))
                    ])
                `shouldBe`
                    [ LoadColumn Nothing "id"
                    , LoadConst (LitInt 1)
                    , LoadConst (LitInt 2)
                    , LoadConst (LitInt 3)
                    , InList 3 ]

            it "compiles NotInExpr as InList + Not" $
                compileExpr (P.NotInExpr (P.Column Nothing "status")
                    [P.Literal (Just (LitText "banned")), P.Literal (Just (LitText "deleted"))])
                `shouldBe`
                    [ LoadColumn Nothing "status"
                    , LoadConst (LitText "banned")
                    , LoadConst (LitText "deleted")
                    , InList 2
                    , UnaryOpInstr Not ]

        describe "nested expression" $
            it "compiles deeply nested expression correctly" $
                -- (a + b) * (c - 1)
                compileExpr (P.BinaryOp BinMul
                    (P.BinaryOp BinAdd (P.Column Nothing "a") (P.Column Nothing "b"))
                    (P.BinaryOp BinSub (P.Column Nothing "c") (P.Literal (Just (LitInt 1)))))
                `shouldBe`
                    [ LoadColumn Nothing "a"
                    , LoadColumn Nothing "b"
                    , BinaryOpInstr Add
                    , LoadColumn Nothing "c"
                    , LoadConst (LitInt 1)
                    , BinaryOpInstr Sub
                    , BinaryOpInstr Mul ]

    -- ────────────────────────────────────────────────────────────────────
    -- 2. Plan compilation — SELECT plans
    -- ────────────────────────────────────────────────────────────────────

    describe "compile (SELECT plans)" $ do

        describe "EmptyResult" $
            it "compiles EmptyResult to [Halt]" $
                instrs EmptyResult `shouldBe` [Halt]

        describe "bare Scan" $
            it "compiles Scan to open/loop/advance/emit/jump/close/halt" $ do
                let plan = mkScan "users" Nothing
                let is   = instrs plan
                -- Check structure: OpenScan, Label, JumpIfExhausted, AdvanceCursor,
                -- BeginRow, (wildcard), EmitRow, Jump, Label, CloseScan, Halt
                head is `shouldBe` OpenScan "users" (Just "users")
                last is `shouldBe` Halt
                is `shouldContain` [AdvanceCursor (Just "users")]
                is `shouldContain` [BeginRow]
                is `shouldContain` [EmitRow]
                is `shouldContain` [CloseScan (Just "users")]

        describe "Scan with alias" $
            it "uses alias in cursor instructions" $ do
                let plan = mkScan "orders" (Just "o")
                let is   = instrs plan
                head is `shouldBe` OpenScan "orders" (Just "o")
                is `shouldContain` [AdvanceCursor (Just "o")]
                is `shouldContain` [CloseScan (Just "o")]

        describe "Filter" $
            it "inserts predicate guard before body" $ do
                let pred  = P.BinaryOp BinGt (P.Column Nothing "age") (P.Literal (Just (LitInt 18)))
                let plan  = OptFilter (mkScan "users" Nothing) pred
                let is    = instrs plan
                -- Must contain: the predicate instructions and JumpIfFalse
                is `shouldContain` [LoadColumn Nothing "age"]
                is `shouldContain` [LoadConst (LitInt 18)]
                is `shouldContain` [BinaryOpInstr Gt]
                -- JumpIfFalse must appear (label is generated, so check for any)
                let hasJumpIfFalse = any (\i -> case i of JumpIfFalse _ -> True; _ -> False) is
                hasJumpIfFalse `shouldBe` True

        describe "Project" $ do
            it "emits EmitColumn for named output columns" $ do
                let cols = [ OutputExpr (P.Column (Just "u") "name") Nothing
                           , OutputExpr (P.Column (Just "u") "age") (Just "years")
                           ]
                let plan = OptProject (mkScan "users" (Just "u")) cols
                let is   = instrs plan
                is `shouldContain` [EmitColumn "name"]
                is `shouldContain` [EmitColumn "years"]

            it "emits BeginRow and EmitRow around column emissions" $ do
                let cols = [OutputExpr (P.Column Nothing "id") Nothing]
                let plan = OptProject (mkScan "t" Nothing) cols
                let is   = instrs plan
                is `shouldContain` [BeginRow]
                is `shouldContain` [EmitRow]

        describe "Sort (post-op)" $
            it "appends SortResult after the scan loop" $ do
                let key  = SortKey (P.Column Nothing "name") P.SortAsc P.NullsLast
                let plan = OptSort (mkScan "users" Nothing) [key]
                let is   = instrs plan
                -- CloseScan must appear before SortResult
                let closeIdx = length (takeWhile (/= CloseScan (Just "users")) is)
                let sortIdx  = length (takeWhile (\i -> case i of SortResult _ -> False; _ -> True) is)
                sortIdx > closeIdx `shouldBe` True
                let hasSortResult = any (\i -> case i of SortResult _ -> True; _ -> False) is
                hasSortResult `shouldBe` True

        describe "Limit (post-op)" $
            it "appends LimitResult after the scan loop" $ do
                let plan = OptLimit (mkScan "t" Nothing) (Just 10) (Just 0)
                let is   = instrs plan
                is `shouldContain` [LimitResult (Just 10) (Just 0)]

        describe "Distinct (post-op)" $
            it "appends DistinctResult after the scan loop" $ do
                let plan = OptDistinct (mkScan "t" Nothing)
                let is   = instrs plan
                is `shouldContain` [DistinctResult]

        describe "Sort + Limit + Distinct (stacked post-ops)" $
            it "emits all three post-ops" $ do
                let key  = SortKey (P.Column Nothing "id") P.SortDesc P.NullsFirst
                let plan = OptLimit (OptSort (OptDistinct (mkScan "t" Nothing)) [key]) (Just 5) Nothing
                let is   = instrs plan
                let hasSortResult  = any (\i -> case i of SortResult _    -> True; _ -> False) is
                let hasLimitResult = any (\i -> case i of LimitResult _ _ -> True; _ -> False) is
                hasSortResult  `shouldBe` True
                hasLimitResult `shouldBe` True
                is `shouldContain` [DistinctResult]

        describe "simple Aggregate (COUNT_STAR)" $ do
            let aggItem = AggregateItem AggCount AggStar "_agg0" False
            let plan = OptAggregate (mkScan "orders" Nothing) [] [aggItem]

            it "starts with InitAgg 1" $
                head (instrs plan) `shouldBe` InitAgg 1

            it "contains UpdateAgg 0 CountStar inside the scan" $ do
                let is = instrs plan
                is `shouldContain` [UpdateAgg 0 CountStar]

            it "contains FinalizeAgg 0 Count in emit phase" $ do
                let is = instrs plan
                is `shouldContain` [FinalizeAgg 0 Count]

        describe "Aggregate SUM" $ do
            let aggItem = AggregateItem AggSum (AggExprArg (P.Column Nothing "price")) "_agg0" False
            let plan = OptAggregate (mkScan "items" Nothing) [] [aggItem]

            it "starts with InitAgg 1" $
                head (instrs plan) `shouldBe` InitAgg 1

            it "contains UpdateAgg 0 Sum" $
                instrs plan `shouldContain` [UpdateAgg 0 Sum]

            it "contains FinalizeAgg 0 Sum" $
                instrs plan `shouldContain` [FinalizeAgg 0 Sum]

        describe "Aggregate AVG" $ do
            let aggItem = AggregateItem AggAvg (AggExprArg (P.Column Nothing "score")) "_agg0" False
            let plan = OptAggregate (mkScan "students" Nothing) [] [aggItem]

            it "contains UpdateAgg 0 Avg" $
                instrs plan `shouldContain` [UpdateAgg 0 Avg]

            it "contains FinalizeAgg 0 Avg" $
                instrs plan `shouldContain` [FinalizeAgg 0 Avg]

        describe "Aggregate MIN" $ do
            let aggItem = AggregateItem AggMin (AggExprArg (P.Column Nothing "val")) "_agg0" False
            let plan = OptAggregate (mkScan "data" Nothing) [] [aggItem]

            it "contains UpdateAgg 0 Min" $
                instrs plan `shouldContain` [UpdateAgg 0 Min]

            it "contains FinalizeAgg 0 Min" $
                instrs plan `shouldContain` [FinalizeAgg 0 Min]

        describe "Aggregate MAX" $ do
            let aggItem = AggregateItem AggMax (AggExprArg (P.Column Nothing "val")) "_agg0" False
            let plan = OptAggregate (mkScan "data" Nothing) [] [aggItem]

            it "contains UpdateAgg 0 Max" $
                instrs plan `shouldContain` [UpdateAgg 0 Max]

            it "contains FinalizeAgg 0 Max" $
                instrs plan `shouldContain` [FinalizeAgg 0 Max]

        describe "Aggregate with GROUP BY" $ do
            let aggItem = AggregateItem AggCount AggStar "_agg0" False
            let grpExpr = P.Column Nothing "dept"
            let plan = OptAggregate (mkScan "employees" Nothing) [grpExpr] [aggItem]

            it "contains SaveGroupKey [\"dept\"]" $
                instrs plan `shouldContain` [SaveGroupKey ["dept"]]

            it "contains LoadGroupKey 0 for emit phase" $
                instrs plan `shouldContain` [LoadGroupKey 0]

        describe "Having" $ do
            let aggItem = AggregateItem AggCount AggStar "_agg0" False
            let havingPred = P.BinaryOp BinGt (P.Column Nothing "_agg0") (P.Literal (Just (LitInt 5)))
            let plan = OptHaving
                            (OptAggregate (mkScan "t" Nothing) [] [aggItem])
                            havingPred

            it "contains JumpIfFalse for having guard" $ do
                let is = instrs plan
                let hasHavingJump = any (\i -> case i of JumpIfFalse _ -> True; _ -> False) is
                hasHavingJump `shouldBe` True

        describe "Project wrapping Aggregate" $ do
            let aggItem = AggregateItem AggCount AggStar "total" False
            let plan = OptProject
                            (OptAggregate (mkScan "t" Nothing) [] [aggItem])
                            [OutputExpr (P.AggExpr AggCount AggStar False) (Just "total")]

            it "still starts with InitAgg 1" $
                head (instrs plan) `shouldBe` InitAgg 1

            it "emits FinalizeAgg for the aggregate" $
                instrs plan `shouldContain` [FinalizeAgg 0 Count]

        describe "nested Filter inside Project" $
            it "generates filter guard inside the scan loop" $ do
                let pred = P.BinaryOp BinEq (P.Column Nothing "active") (P.Literal (Just (LitBool True)))
                let plan = OptProject
                                (OptFilter (mkScan "users" Nothing) pred)
                                [OutputExpr (P.Column Nothing "name") Nothing]
                let is = instrs plan
                is `shouldContain` [LoadConst (LitBool True)]
                is `shouldContain` [BinaryOpInstr Eq]
                let hasJumpIfFalse = any (\i -> case i of JumpIfFalse _ -> True; _ -> False) is
                hasJumpIfFalse `shouldBe` True

    -- ────────────────────────────────────────────────────────────────────
    -- 3. Plan compilation — DML
    -- ────────────────────────────────────────────────────────────────────

    describe "compile (DML)" $ do

        describe "INSERT" $ do
            it "compiles single-row INSERT with columns" $ do
                let vals = [[P.Literal (Just (LitInt 1)), P.Literal (Just (LitText "Alice"))]]
                let plan = OptInsert "users" ["id", "name"] vals
                let is   = instrs plan
                is `shouldContain` [LoadConst (LitInt 1)]
                is `shouldContain` [LoadConst (LitText "Alice")]
                is `shouldContain` [InsertRow "users" (Just ["id", "name"])]
                last is `shouldBe` Halt

            it "compiles multi-row INSERT" $ do
                let vals = [ [P.Literal (Just (LitInt 1))]
                           , [P.Literal (Just (LitInt 2))]
                           ]
                let plan = OptInsert "t" ["id"] vals
                let is   = instrs plan
                let insertRows = [i | i@(InsertRow _ _) <- is]
                length insertRows `shouldBe` 2

            it "compiles INSERT with no column list" $ do
                let vals = [[P.Literal (Just (LitInt 42))]]
                let plan = OptInsert "t" [] vals
                let is   = instrs plan
                is `shouldContain` [InsertRow "t" Nothing]

        describe "UPDATE" $ do
            it "compiles UPDATE without WHERE to scan + UpdateRows + Halt" $ do
                let plan = OptUpdate "users" [] Nothing
                let is   = instrs plan
                head is `shouldBe` OpenScan "users" (Just "users")
                is `shouldContain` [UpdateRows "users"]
                last is `shouldBe` Halt

            it "compiles UPDATE with WHERE adds JumpIfFalse guard" $ do
                let pred = P.BinaryOp BinEq (P.Column Nothing "id") (P.Literal (Just (LitInt 5)))
                let plan = OptUpdate "users" [] (Just pred)
                let is   = instrs plan
                is `shouldContain` [BinaryOpInstr Eq]
                let hasJumpIfFalse = any (\i -> case i of JumpIfFalse _ -> True; _ -> False) is
                hasJumpIfFalse `shouldBe` True
                is `shouldContain` [UpdateRows "users"]
                last is `shouldBe` Halt

        describe "DELETE" $ do
            it "compiles DELETE without WHERE to scan + DeleteRows + Halt" $ do
                let plan = OptDelete "logs" Nothing
                let is   = instrs plan
                head is `shouldBe` OpenScan "logs" (Just "logs")
                is `shouldContain` [DeleteRows "logs"]
                last is `shouldBe` Halt

            it "compiles DELETE with WHERE adds JumpIfFalse guard" $ do
                let pred = P.BinaryOp BinLt (P.Column Nothing "age") (P.Literal (Just (LitInt 18)))
                let plan = OptDelete "users" (Just pred)
                let is   = instrs plan
                is `shouldContain` [BinaryOpInstr Lt]
                let hasJumpIfFalse = any (\i -> case i of JumpIfFalse _ -> True; _ -> False) is
                hasJumpIfFalse `shouldBe` True
                is `shouldContain` [DeleteRows "users"]
                last is `shouldBe` Halt

    -- ────────────────────────────────────────────────────────────────────
    -- 4. Plan compilation — DDL
    -- ────────────────────────────────────────────────────────────────────

    describe "compile (DDL)" $ do

        describe "CREATE TABLE" $ do
            it "compiles CreateTable to [CreateTableInstr, Halt]" $ do
                let plan = OptCreateTable "users" False [colDef "id", colDef "name"]
                let is   = instrs plan
                length is `shouldBe` 2
                head is `shouldBe` CreateTableInstr "users" False [colDef "id", colDef "name"]
                last is `shouldBe` Halt

            it "respects IF NOT EXISTS flag" $ do
                let plan = OptCreateTable "t" True [colDef "x"]
                let is   = instrs plan
                head is `shouldBe` CreateTableInstr "t" True [colDef "x"]

        describe "DROP TABLE" $ do
            it "compiles DropTable to [DropTableInstr, Halt]" $ do
                let plan = OptDropTable "old_table" False
                let is   = instrs plan
                length is `shouldBe` 2
                head is `shouldBe` DropTableInstr "old_table" False
                last is `shouldBe` Halt

            it "respects IF EXISTS flag" $ do
                let plan = OptDropTable "t" True
                let is   = instrs plan
                head is `shouldBe` DropTableInstr "t" True

    -- ────────────────────────────────────────────────────────────────────
    -- 5. Label uniqueness and determinism
    -- ────────────────────────────────────────────────────────────────────

    describe "label uniqueness" $ do

        it "compiling the same plan twice produces the same labels" $ do
            let plan = OptFilter (mkScan "t" Nothing)
                            (P.BinaryOp BinGt (P.Column Nothing "x") (P.Literal (Just (LitInt 0))))
            instrs plan `shouldBe` instrs plan

        it "nested scan (join) produces different label suffixes for each loop" $ do
            let plan = OptJoin (mkScan "a" Nothing) (mkScan "b" Nothing) P.JoinInner Nothing
            let is   = instrs plan
            let labels = [n | Label n <- is]
            -- There should be at least 2 distinct loop labels (one per table)
            length (filter (isPrefixOf "loop_") labels) >= 2 `shouldBe` True

    -- ────────────────────────────────────────────────────────────────────
    -- 6. Program structure invariants
    -- ────────────────────────────────────────────────────────────────────

    describe "Program invariants" $ do

        it "every compiled plan ends with Halt" $ do
            let plans =
                    [ mkScan "t" Nothing
                    , OptFilter (mkScan "t" Nothing) (P.Literal (Just (LitBool True)))
                    , OptProject (mkScan "t" Nothing) [OutputExpr (P.Column Nothing "x") Nothing]
                    , OptInsert "t" [] [[P.Literal (Just (LitInt 1))]]
                    , OptDelete "t" Nothing
                    , OptUpdate "t" [] Nothing
                    , OptCreateTable "t" False [colDef "id"]
                    , OptDropTable "t" False
                    , EmptyResult
                    ]
            mapM_ (\p -> last (instrs p) `shouldBe` Halt) plans

        it "non-empty plans produce more than 1 instruction" $ do
            let is = instrs (mkScan "t" Nothing)
            length is > 1 `shouldBe` True

-- ── Helper for string prefix check ────────────────────────────────────────

isPrefixOf :: String -> String -> Bool
isPrefixOf [] _         = True
isPrefixOf _  []        = False
isPrefixOf (x:xs) (y:ys) = x == y && isPrefixOf xs ys
